def find_rs_files(alias):
    root=os.path.join(BASE,alias)
    rs=[]
    for dirpath,_,files in os.walk(root):
        # skip node, web, etc? keep all
        for f in files:
            if f.endswith(".rs") or f.endswith(".py") or f.endswith(".toml"):
                full=os.path.join(dirpath,f)
                try:
                    sz=os.path.getsize(full)
                except: sz=0
                rel=os.path.relpath(full,root)
                rs.append((rel,sz))
    return sorted(rs)

