def md5(path):
    try:
        return hashlib.md5(open(path,'rb').read()).hexdigest()[:8]
    except: return "MISS"

def wc(path):
    try: return sum(1 for _ in open(path,encoding='utf-8',errors='ignore'))
    except: return 0

