327: fn draw_graph(app: &mut SmartApp, ui: &mut Ui, body: Rect, th: &Theme) {
328:     let p = ui.painter().clone();
329:     let home = app.be.home();
330:     let mut nodes: Vec<(String, String, usize, u64, usize)> = vec![]; // label, path, depth, bytes, parent idx
331:     #[cfg(not(target_arch = "wasm32"))]
332:     if !app.be.demo {
333:         if let Ok(rd) = std::fs::read_dir(&home.path) {
334:             for e in rd.flatten() {
335:                 let Ok(m) = e.metadata() else { continue };
336:                 if !m.is_dir() {
337:                     continue;
338:                 }
339:                 let mut ff = 0;
340:                 let b = dir_size(&e.path(), 3, &mut ff);
341:                 let pi = nodes.len();
342:                 nodes.push((e.file_name().to_string_lossy().to_string(), e.path().to_string_lossy().into_owned(), 1, b, 0));
343:                 if pi < 6 {
344:                     if let Ok(rd2) = std::fs::read_dir(e.path()) {
345:                         for e2 in rd2.flatten().take(5) {
346:                             if e2.metadata().map(|m| m.is_dir()).unwrap_or(false) {
347:                                 let mut ff2 = 0;
348:                                 let b2 = dir_size(&e2.path(), 2, &mut ff2);
349:                                 nodes.push((e2.file_name().to_string_lossy().to_string(), e2.path().to_string_lossy().into_owned(), 2, b2, pi));
350:                             }
351:                         }
352:                     }
353:                 }
354:             }
355:         }
356:     }
357:     let c = body.center();
358:     let maxb = nodes.iter().map(|n| n.3).max().unwrap_or(1).max(1);
359:     let pos_of = |i: usize| -> Pos2 {
360:         let n = &nodes[i];
361:         if n.2 == 1 {
362:             let ones = nodes.iter().filter(|m| m.2 == 1).count().max(1);
363:             let idx = nodes[..i].iter().filter(|m| m.2 == 1).count();
364:             let ang = (idx as f32 / ones as f32) * std::f32::consts::TAU - std::f32::consts::FRAC_PI_2;
365:             let rad = body.width().min(body.height()) * 0.30;
366:             pos2(c.x + ang.cos() * rad, c.y + ang.sin() * rad * 0.82)
367:         } else {
368:             let pp = pos_of_parent(&nodes, i, c, body);
369:             pp
370:         }
371:     };
372:     fn pos_of_parent(nodes: &[(String, String, usize, u64, usize)], i: usize, c: Pos2, body: Rect) -> Pos2 {
373:         let n = &nodes[i];
374:         let pi = n.4;
375:         let ones = nodes.iter().filter(|m| m.2 == 1).count().max(1);
376:         let idx = nodes[..pi].iter().filter(|m| m.2 == 1).count();
377:         let ang = (idx as f32 / ones as f32) * std::f32::consts::TAU - std::f32::consts::FRAC_PI_2;
378:         let rad = body.width().min(body.height()) * 0.30;
379:         let base = pos2(c.x + ang.cos() * rad, c.y + ang.sin() * rad * 0.82);
380:         let kids: Vec<usize> = nodes.iter().enumerate().filter(|(_, m)| m.2 == 2 && m.4 == pi).map(|(j, _)| j).collect();
381:         let ki = kids.iter().position(|&j| j == i).unwrap_or(0) as f32;
382:         let kn = kids.len().max(1) as f32;
383:         let spread = (ki - (kn - 1.0) / 2.0) * 0.22;
384:         pos2(base.x + (ang + spread).cos() * 74.0, base.y + (ang + spread).sin() * 74.0)
385:     }
386:     // edges
387:     for i in 0..nodes.len() {
388:         if nodes[i].2 == 2 {
389:             let a = pos_of_parent(&nodes, i, c, body);
390:             let pi = nodes[i].4;
391:             let ones = nodes.iter().filter(|m| m.2 == 1).count().max(1);
392:             let idx = nodes[..pi].iter().filter(|m| m.2 == 1).count();
393:             let ang = (idx as f32 / ones as f32) * std::f32::consts::TAU - std::f32::consts::FRAC_PI_2;
394:             let rad = body.width().min(body.height()) * 0.30;
395:             let b = pos2(c.x + ang.cos() * rad, c.y + ang.sin() * rad * 0.82);
396:             p.line_segment([a, b], egui::Stroke::new(1.0, alpha(th.accent, 0.22)));
397:         }
398:     }
399:     for i in 0..nodes.len() {
400:         let n = nodes[i].clone();
401:         let pos = if n.2 == 1 { pos_of(i) } else { pos_of_parent(&nodes, i, c, body) };
402:         let r = (6.0 + 20.0 * (n.3 as f32 / maxb as f32).sqrt()).min(28.0);
403:         let resp = app.hit(ui, Rect::from_center_size(pos, vec2(r * 2.0, r * 2.0)), ("node", i), Sense::click());
404:         let col = if n.2 == 1 { th.accent } else { alpha(th.accent, 0.55) };
405:         p.circle_filled(pos, r, alpha(col, if resp.hovered() { 0.5 } else { 0.26 }));
406:         p.circle_stroke(pos, r, egui::Stroke::new(1.4, col));
407:         if n.2 == 1 {
408:             p.text(pos2(pos.x, pos.y + r + 11.0), Align2::CENTER_CENTER, app.fit(&p, &n.0, &f_medium(10.0), 90.0), f_medium(10.0), th.ink2);
409:         }
410:         if resp.hovered() {
411:             p.text(pos2(pos.x, pos.y - r - 9.0), Align2::CENTER_CENTER, format!("{} · {}", n.0, format_size(n.3)), f_semi(T_META), th.ink1);
412:             ui.ctx().request_repaint();
413:         }
414:         if resp.clicked() && n.2 == 1 {
415:             app.push_act(Act::Nav(Route::Loc(Location::new("file", n.1.clone()))));
416:         }
417:     }
418:     if nodes.is_empty() {
419:         p.text(c, Align2::CENTER_CENTER, "The folder graph runs on the desktop build.", f_medium(T_META), th.ink3);
420:     }
421:     let _ = (home, pos_of);
422: }

