221: impl SmartApp {
222:     fn native_resize_grips(&mut self, ctx: &egui::Context) {
223:         if IS_WEB {
224:             return;
225:         }
226:         use egui::viewport::ResizeDirection as D;
227:         let r = ctx.content_rect();
228:         let Some(p) = ctx.pointer_latest_pos() else { return };
229:         let m = 6.0;
230:         let (l, rr, t, b) = (p.x - r.left() < m, r.right() - p.x < m, p.y - r.top() < m, r.bottom() - p.y < m);
231:         let dir = match (l, rr, t, b) {
232:             (true, _, true, _) => Some(D::NorthWest),
233:             (_, true, true, _) => Some(D::NorthEast),
234:             (true, _, _, true) => Some(D::SouthWest),
235:             (_, true, _, true) => Some(D::SouthEast),
236:             (true, ..) => Some(D::West),
237:             (_, true, ..) => Some(D::East),
238:             (_, _, true, _) => Some(D::North),
239:             (_, _, _, true) => Some(D::South),
240:             _ => None,
241:         };
242:         if let Some(d) = dir {
243:             ctx.set_cursor_icon(match d {
244:                 D::North | D::South => egui::CursorIcon::ResizeVertical,
245:                 D::East | D::West => egui::CursorIcon::ResizeHorizontal,
246:                 D::NorthWest | D::SouthEast => egui::CursorIcon::ResizeNwSe,
247:                 _ => egui::CursorIcon::ResizeNeSw,
248:             });
249:             if ctx.input(|i| i.pointer.primary_pressed()) {
250:                 ctx.send_viewport_cmd(egui::ViewportCommand::BeginResize(d));
251:             }
252:         }
253:     }
