255:     fn handle_keys(&mut self, ctx: &egui::Context) {
256:         use egui::Key;
257:         // the focused suite app (Terminal / Photos) owns the keyboard
258:         if IS_WEB && self.focused_app() != crate::shell::AppId::Files {
259:             let (cmd, k, comma) = ctx.input(|i| (i.modifiers.command, i.key_pressed(Key::K), i.key_pressed(Key::Comma)));
260:             if cmd && k {
261:                 self.act(Act::Palette);
262:             } else if cmd && comma {
263:                 self.app_cmd("settings");
264:             }
265:             return;
266:         }
267:         let typing = ctx.egui_wants_keyboard_input();
268:         let (cmd, shift, alt) = ctx.input(|i| (i.modifiers.command, i.modifiers.shift, i.modifiers.alt));
269:         let pressed = |k: Key| ctx.input(|i| i.key_pressed(k));
270:         let events: Vec<egui::Event> = ctx.input(|i| i.events.clone());
271:         if cmd && pressed(Key::K) {
272:             self.act(Act::Palette);
273:             return;
274:         }
275:         if cmd && pressed(Key::T) && !typing {
276:             self.act(Act::NewTab(None));
277:             return;
278:         }
279:         if cmd && pressed(Key::W) && !typing && self.tabs.len() > 1 {
280:             self.act(Act::CloseTab(self.tab_i));
281:             return;
282:         }
283:         if cmd && pressed(Key::Comma) {
284:             self.act(Act::Settings);
285:             return;
286:         }
287:         if pressed(Key::Escape) && self.search.sheet {
288:             self.act(Act::SearchSheet(false));
289:             return;
290:         }
291:         if pressed(Key::Escape) {
292:             if self.palette.open {
293:                 // palette handles its own Esc
294:             } else if self.menu.is_some() {
295:                 self.menu = None;
296:             } else if !matches!(self.modal, Modal::None) {
297:                 if let Modal::Preview(_) = self.modal {
298:                     self.be.audio.stop();
299:                 }
300:                 self.act(Act::CloseModal);
301:             } else if self.rename.is_some() {
302:                 self.rename = None;
303:             } else if self.ai.open && !typing {
304:                 self.ai.open = false;
305:             } else if self.search_active() {
306:                 self.clear_search();
307:             } else if !typing {
308:                 self.sel.clear();
309:                 self.select_mode = false;
310:             }
311:             return;
312:         }
313:         if self.palette.open {
314:             return;
315:         }
316:         // preview navigation
317:         if let Modal::Preview(l) = self.modal.clone() {
318:             let list: Vec<Location> = self.items.iter().filter(|x| x.kind.previewable()).map(|x| x.loc.clone()).collect();
319:             if let Some(i) = list.iter().position(|x| *x == l) {
320:                 if pressed(Key::ArrowRight) && i + 1 < list.len() {
321:                     self.act(Act::Preview(list[i + 1].clone()));
322:                 }
323:                 if pressed(Key::ArrowLeft) && i > 0 {
324:                     self.act(Act::Preview(list[i - 1].clone()));
325:                 }
326:             }
327:             if pressed(Key::Space) && !typing {
328:                 self.be.audio.stop();
329:                 self.act(Act::CloseModal);
330:             }
331:             return;
332:         }
333:         if !matches!(self.modal, Modal::None) {
334:             return;
335:         }
336:         if alt && pressed(Key::ArrowLeft) {
337:             self.act(Act::Back);
338:         }
339:         if alt && pressed(Key::ArrowRight) {
340:             self.act(Act::Forward);
341:         }
342:         if cmd && pressed(Key::Backslash) {
343:             self.act(Act::ToggleSidebar);
344:         }
345:         if cmd && pressed(Key::F) {
346:             self.act(Act::FocusSearch);
347:         }
348:         if pressed(Key::F5) {
349:             self.act(Act::Refresh);
350:         }
351:         // window-level shortcuts work even while a text field has focus
352:         if cmd && pressed(Key::Q) {
353:             return self.act(Act::WinClose);
354:         }
355:         if pressed(Key::F11) {
356:             self.act(Act::Native(NativeCmd::ToggleFullscreen));
357:         }
358:         if pressed(Key::F1) {
359:             return self.act(Act::Modal(Modal::Shortcuts));
360:         }
361:         if cmd && !shift && pressed(Key::N) && !typing {
362:             self.act(Act::Native(NativeCmd::NewWindow));
363:         }
364:         if cmd && pressed(Key::Tab) {
365:             self.act(Act::NextTab(!shift));
366:             return;
367:         }
368:         if alt && pressed(Key::Home) {
369:             self.act(Act::Home);
370:         }
371:         if typing {
372:             return;
373:         }
374:         if cmd && !shift && pressed(Key::Z) {
375:             self.act(Act::Undo);
376:         }
377:         if cmd && shift && pressed(Key::C) {
378:             self.act(Act::CopyPath);
379:         }
380:         if cmd && shift && pressed(Key::I) {
381:             self.act(Act::InvertSelection);
382:         } else if cmd && pressed(Key::I) {
383:             self.act(Act::Info);
384:         }
385:         if cmd && (pressed(Key::Plus) || pressed(Key::Equals)) {
386:             let z = (self.st().thumb_scale + 0.1).clamp(0.75, 1.4);
387:             self.act(Act::SetGridZoom(z));
388:         }
389:         if cmd && pressed(Key::Minus) {
390:             let z = (self.st().thumb_scale - 0.1).clamp(0.75, 1.4);
391:             self.act(Act::SetGridZoom(z));
392:         }
393:         if cmd && pressed(Key::O) {
394:             self.act(Act::OpenSel);
395:         }
396:         // Home / End / PageUp / PageDown move the focus like every other file manager
397:         if !self.items.is_empty() && !cmd && !alt {
398:             let n = self.items.len();
399:             let page = if self.st().grid { (self.cols.max(1) * 3) as i32 } else { 10 };
400:             let cur = self.focus.unwrap_or(0) as i32;
401:             let to = if pressed(Key::Home) { Some(0) } else if pressed(Key::End) { Some(n as i32 - 1) } else if pressed(Key::PageDown) { Some(cur + page) } else if pressed(Key::PageUp) { Some(cur - page) } else { None };
402:             if let Some(t) = to {
403:                 let next = t.clamp(0, n as i32 - 1) as usize;
404:                 self.focus = Some(next);
405:                 if shift {
406:                     let a = self.anchor.unwrap_or(cur as usize);
407:                     let (lo, hi) = (a.min(next), a.max(next));
408:                     self.sel = self.items[lo..=hi].iter().map(|e| e.loc.clone()).collect();
409:                 } else {
410:                     self.sel = [self.items[next].loc.clone()].into_iter().collect();
411:                     self.anchor = Some(next);
412:                 }
413:                 self.scroll_to = Some(next);
414:             }
415:         }
416:         for e in &events {
417:             match e {
418:                 egui::Event::Copy if !shift => self.act(Act::Copy),
419:                 egui::Event::Cut => self.act(Act::Cut),
420:                 egui::Event::Paste(_) => self.act(Act::Paste),
421:                 _ => {}
422:             }
423:         }
424:         if cmd && pressed(Key::A) {
425:             self.act(Act::SelectAll);
426:         }
427:         if cmd && pressed(Key::D) {
428:             self.act(Act::Duplicate);
429:         }
430:         if cmd && pressed(Key::H) {
431:             self.act(Act::ToggleHidden);
432:         }
433:         if cmd && shift && pressed(Key::N) {
434:             self.act(Act::NewFolder);
435:         }
436:         if pressed(Key::F2) {
437:             if let Some(e) = self.selected().first() {
438:                 self.act(Act::Rename(e.loc.clone()));
439:             }
440:         }
441:         if pressed(Key::Delete) || (cmd && pressed(Key::Backspace)) {
442:             self.act(if shift { Act::DeleteForever } else { Act::Trash });
443:         }
444:         if pressed(Key::Enter) {
445:             self.act(Act::OpenSel);
446:         }
447:         if pressed(Key::Space) {
448:             let s = self.selected();
449:             if s.len() == 1 && s[0].kind.previewable() {
450:                 self.act(Act::Preview(s[0].loc.clone()));
451:             } else if s.len() == 1 && s[0].kind == smart_core::Kind::Audio {
452:                 self.act(Act::TogglePlayPause(s[0].loc.clone()));
453:             }
454:         }
455:         if (pressed(Key::Backspace) && !cmd) || (alt && pressed(Key::ArrowUp)) {
456:             self.act(Act::Up);
457:         }
458:         // arrow navigation
459:         if !self.search_active() && !self.items.is_empty() {
460:             let grid = self.st().grid;
461:             let cols = if grid { self.cols as i32 } else { 1 };
462:             let mut d = 0i32;
463:             if pressed(Key::ArrowRight) && grid { d = 1 }
464:             if pressed(Key::ArrowLeft) && grid { d = -1 }
465:             if pressed(Key::ArrowDown) { d = cols }
466:             if pressed(Key::ArrowUp) { d = -cols }
467:             if !alt && d != 0 {
468:                 let n = self.items.len() as i32;
469:                 let cur = self.focus.map(|f| f as i32).unwrap_or(if d > 0 { -cols.min(1) } else { n });
470:                 let next = (cur + d).clamp(0, n - 1) as usize;
471:                 self.focus = Some(next);
472:                 let loc = self.items[next].loc.clone();
473:                 if shift {
474:                     let a = self.anchor.unwrap_or(next);
475:                     let (lo, hi) = (a.min(next), a.max(next));
476:                     self.sel = self.items[lo..=hi].iter().map(|e| e.loc.clone()).collect();
477:                 } else {
478:                     self.sel = [loc].into_iter().collect();
479:                     self.anchor = Some(next);
480:                 }
481:                 self.scroll_to = Some(next);
482:             }
483:         }
484:         // single-key shortcuts (match the status-bar hints) and type-to-search
485:         if !cmd && !alt {
486:             if pressed(Key::G) { return self.act(Act::SetGrid(true)); }
487:             if pressed(Key::L) { return self.act(Act::SetGrid(false)); }
488:             if pressed(Key::D) { return self.act(Act::ToggleTheme); }
489:             if pressed(Key::T) { return self.act(Act::Modal(Modal::Tokens)); }
490:             if pressed(Key::Questionmark) { return self.act(Act::Modal(Modal::Shortcuts)); }
491:             if pressed(Key::Slash) { return self.act(Act::FocusSearch); }
492:             for e in &events {
493:                 if let egui::Event::Text(t) = e {
494:                     if t.chars().all(|c| !c.is_control()) && !t.trim().is_empty() && self.rename.is_none() {
495:                         self.search.query = t.clone();
496:                         self.search.dirty_at = self.time;
497:                         self.search.focus_next = true;
498:                         self.run_search();
499:                         return;
500:                     }
501:                 }
502:             }
503:         }
504:     }
505: }
