507: pub fn make_app(cc: &eframe::CreationContext<'_>) -> SmartApp {
508:     let mut a = SmartApp::new(cc, None);
509:     a.seed_demo_tags();
510:     #[cfg(not(target_arch = "wasm32"))]
511:     if let Some(p) = native::START.get() {
512:         let path = std::fs::canonicalize(p).unwrap_or_else(|_| p.into());
513:         if path.is_dir() {
514:             a.act(Act::Nav(Route::Loc(Location::file(path.to_string_lossy().replace('\\', "/")))));
