524: /// `#terminal=ls;neofetch`, `#photos`, `#photo` / `#photo=edit` / `#photo=info`, `#menu` — open the suite in a given state
525: /// (handy for sharing a view and for automated screenshots).
526: #[cfg(target_arch = "wasm32")]
527: fn deep_link(a: &mut SmartApp) {
528:     use crate::shell::AppId;
529:     let h = web_sys::window().and_then(|w| w.location().hash().ok()).unwrap_or_default();
530:     let h = h.trim_start_matches('#');
531:     let (name, arg) = h.split_once('=').unwrap_or((h, ""));
532:     match name {
533:         "terminal" => {
534:             a.open_app(AppId::Terminal);
535:             a.shell.term.command("new");
536:             for c in arg.split(';').filter(|c| !c.is_empty()) {
537:                 a.term_submit(0, c.replace("%20", " "));
538:             }
539:         }
540:         "photos" => a.open_app(AppId::Photos),
541:         "top" => {
542:             a.open_app(AppId::Terminal);
543:             a.shell.term.command("new");
544:             a.term_submit(0, "top".into());
545:         }
546:         "palette" => {
547:             match arg {
548:                 "photos" => a.open_app(AppId::Photos),
549:                 "terminal" => a.open_app(AppId::Terminal),
550:                 _ => {}
551:             }
552:             a.act(Act::Palette);
553:         }
554:         "settings" => {
555:             let app = if arg == "terminal" { AppId::Terminal } else { AppId::Photos };
556:             a.open_app(app);
557:             a.shell.settings = Some((app, 0));
558:         }
559:         "photomenu" => {
560:             a.open_app(AppId::Photos);
561:             if arg == "viewer" {
562:                 if let Some(l) = a.photos_first() {
563:                     a.photos_show(l);
564:                 }
565:                 let items = a.photos_viewer_menu();
566:                 a.open_app_menu(egui::pos2(760.0, 300.0), items);
567:             } else {
568:                 let items = a.photos_library_menu();
569:                 a.open_app_menu(egui::pos2(760.0, 300.0), items);
570:             }
571:         }
572:         "termmenu" => {
573:             a.open_app(AppId::Terminal);
574:             a.shell.term.command("new");
575:             a.term_submit(0, "ls".into());
576:             let items = a.term_menu_main();
577:             a.open_app_menu(egui::pos2(900.0, 300.0), items);
578:         }
579:         "photo" => {
580:             a.open_app(AppId::Photos);
581:             let first = a.photos_first();
582:             if let Some(l) = first {
583:                 a.photos_show(l);
584:             }
585:             a.shell.photos.edit = arg == "edit";
586:             a.shell.photos.info = arg == "info";
587:             if arg == "edit" {
588:                 a.shell.photos.adj = crate::photos::Adjust { exposure: 0.1, contrast: 0.25, saturation: 0.3, warmth: 0.3, vignette: 0.4 };
589:                 a.shell.photos.dirty = true;
590:             }
591:         }
592:         "copy" => {
593:             // starts the paced 5 GB demo transfer so the dialog can be seen straight away
594:             let mut stack = vec![a.be.home()];
595:             let mut found = None;
596:             while let Some(d) = stack.pop() {
597:                 if let Some(fs) = a.be.registry.get(&d.fs) {
598:                     if let Ok(l) = fs.list(&d.path) {
599:                         for e in l {
600:                             if e.paced {
601:                                 found = Some(e.loc.clone());
602:                             } else if e.is_dir {
603:                                 stack.push(e.loc.clone());
604:                             }
605:                         }
606:                     }
607:                 }
608:                 if found.is_some() {
609:                     break;
610:                 }
611:             }
612:             let dest = a.places.iter().find(|p| p.id == "downloads").map(|p| p.loc.clone());
613:             if let (Some(src), Some(d)) = (found, dest) {
614:                 a.submit_job(smart_core::JobKind::Copy { srcs: vec![src], dest: d });
615:             }
616:         }
617:         "menu" => {
618:             a.menu = Some(Menu { kind: MenuKind::More, pos: egui::pos2(1250.0, 130.0), target: None, device: None, sub: None, age: 0.0 });
619:         }
620:         _ => {}
621:     }
622: }
