625: /// Native-only plumbing: command line, crash log, window mode.
626: #[cfg(not(target_arch = "wasm32"))]
627: pub mod native {
628:     use std::sync::atomic::{AtomicBool, Ordering};
629:     use std::sync::OnceLock;
630: 
631:     static OPAQUE: AtomicBool = AtomicBool::new(false);
632:     pub static START: OnceLock<String> = OnceLock::new();
633: 
634:     pub fn opaque() -> bool {
635:         OPAQUE.load(Ordering::Relaxed)
636:     }
637: 
638:     pub const HELP: &str = "Smart Files — a fast, fault-tolerant file manager written in Rust
639: 
640: USAGE:  smart-files [OPTIONS] [FOLDER]
641: 
642: OPTIONS:
643:     --opaque       Draw an opaque window (use when your compositor can't do transparency)
644:     --demo         Browse a built-in in-memory sample world instead of your real files
645:     --crash-log    Print the path of the crash log and exit
646:     -h, --help     Show this help
647:     -V, --version  Show the version
648: 
649: ENVIRONMENT:
650:     SMART_FILES_OPAQUE=1   same as --opaque
651:     WINIT_UNIX_BACKEND     force `x11` or `wayland`
652:     LIBGL_ALWAYS_SOFTWARE  =1 to force software rendering";
653: 
654:     pub fn crash_log_path() -> std::path::PathBuf {
655:         let base = std::env::var_os("XDG_STATE_HOME").map(std::path::PathBuf::from).or_else(|| std::env::var_os("HOME").map(|h| std::path::PathBuf::from(h).join(".local/state"))).unwrap_or_else(std::env::temp_dir);
656:         base.join("smart-files").join("crash.log")
657:     }
