322:     fn draw_grid_overlay(&self, p: &Painter, win: Rect) {
323:         let pp = p.with_clip_rect(win);
324:         let col = alpha(self.th.accent, 0.10);
325:         let major = alpha(self.th.accent, 0.20);
326:         let mut x = win.left();
327:         let mut i = 0;
328:         while x < win.right() {
329:             pp.line_segment([pos2(x, win.top()), pos2(x, win.bottom())], egui::Stroke::new(1.0, if i % 8 == 0 { major } else { col }));
330:             x += 8.0;
331:             i += 1;
332:         }
333:         let mut y = win.top();
334:         i = 0;
335:         while y < win.bottom() {
336:             pp.line_segment([pos2(win.left(), y), pos2(win.right(), y)], egui::Stroke::new(1.0, if i % 8 == 0 { major } else { col }));
337:             y += 8.0;
338:             i += 1;
339:         }
340:         let r = Rect::from_min_size(win.left_bottom() + vec2(16.0, -52.0), vec2(250.0, 28.0));
341:         grad_fill(&pp, r, 14.0, alpha(self.th.accent, 0.95), alpha(self.th.accent, 0.85));
342:         pp.text(r.center(), Align2::CENTER_CENTER, "8 px grid \u{b7} 64 px major \u{b7} 4 px baseline", f_semi(11.0), self.th.on_accent());
343:     }
