346:     fn traffic(&self, ui: &Ui, origin: Pos2, id: &str) {
347:         let p = ui.painter();
348:         let cols = [("close", hex("#ff7c72"), hex("#f2554c")), ("min", hex("#ffd264"), hex("#f5b93c")), ("zoom", hex("#6fdc8c"), hex("#38bd62"))];
349:         let group = Rect::from_min_size(origin - vec2(2.0, 8.0), vec2(64.0, 16.0));
350:         let g_hover = ui.rect_contains_pointer(group);
351:         for (i, (n, a, b)) in cols.iter().enumerate() {
352:             let ctr = origin + vec2(6.0 + 20.0 * i as f32, 0.0);
353:             let rect = Rect::from_center_size(ctr, vec2(16.0, 16.0));
354:             let resp = self.hit(ui, rect, (id, n), Sense::click());
355:             let s = if resp.hovered() { 1.14 } else { 1.0 };
356:             let dot = Rect::from_center_size(ctr, vec2(12.0 * s, 12.0 * s));
357:             shadow(p, dot, 6.0, 0.5, 1.0, 0.0, c(20, 29, 48, 0.12));
358:             let (a, b) = if resp.is_pointer_button_down_on() { (mix(*a, Color32::BLACK, 0.12), mix(*b, Color32::BLACK, 0.12)) } else { (*a, *b) };
359:             grad_fill(p, dot, 6.0 * s, a, b);
360:             rim(p, dot, 6.0, 1.0, Color32::from_white_alpha(95), true, 7.0);
361:             if g_hover {
362:                 let k = c(40, 20, 18, 0.55);
363:                 let st = egui::Stroke::new(1.35, k);
364:                 match *n {
365:                     "close" => {
366:                         p.line_segment([ctr + vec2(-2.8, -2.8), ctr + vec2(2.8, 2.8)], st);
367:                         p.line_segment([ctr + vec2(2.8, -2.8), ctr + vec2(-2.8, 2.8)], st);
368:                     }
369:                     "min" => {
370:                         p.line_segment([ctr + vec2(-3.0, 0.0), ctr + vec2(3.0, 0.0)], st);
371:                     }
372:                     _ => {
373:                         p.line_segment([ctr + vec2(-2.6, 2.6), ctr + vec2(2.6, -2.6)], st);
374:                         p.line_segment([ctr + vec2(2.6, -2.6), ctr + vec2(0.4, -2.6)], st);
375:                         p.line_segment([ctr + vec2(2.6, -2.6), ctr + vec2(2.6, -0.4)], st);
376:                     }
377:                 }
378:             }
379:             if resp.clicked() {
380:                 self.push_act(match *n {
381:                     "close" => Act::WinClose,
382:                     "min" => Act::WinMin,
383:                     _ => Act::WinZoom,
384:                 });
385:             }
386:         }
387:     }
