505:     fn sidebar_rows(&mut self, ui: &Ui, p: &Painter, nav: Rect, dy: f32) {
506:         let th = self.th.clone();
507:         let x0 = nav.left() + 12.0;
508:         let w = SIDEBAR_W - 24.0;
509:         let cur = self.route.clone();
510:         let mut y = nav.top() + dy + 12.0;
511:         let label = |y: f32, s: &str, n: Option<usize>| {
512:             p.text(pos2(nav.left() + 20.0, y + 7.0), Align2::LEFT_CENTER, s.to_uppercase(), f_semi(T_LABEL), th.ink4);
513:             if let Some(n) = n {
514:                 p.text(pos2(nav.left() + 20.0 + 64.0, y + 7.0), Align2::LEFT_CENTER, n.to_string(), f_medium(10.0), alpha(th.ink4, 0.8));
515:             }
516:         };
517:         let base = nav.top() + dy;
518:         // ── Favorites
519:         label(y, "Favorites", None);
520:         y += 22.0;
521:         let mut rows: Vec<(String, &'static str, Route, Option<usize>, Option<Location>)> = vec![];
522:         let places = self.places.clone();
523:         for pl in &places {
524:             rows.push((pl.title.clone(), pl.icon, Route::Loc(pl.loc.clone()), self.place_counts.get(&pl.loc).copied(), Some(pl.loc.clone())));
525:             if pl.id == "home" {
526:                 rows.push(("Recents".into(), "clock-circle", Route::Recents, None, None));
527:             }
528:         }
529:         for pin in self.lib(|l| l.pins.clone()) {
530:             rows.insert(1, (pin.name(), "folder", Route::Loc(pin.clone()), None, Some(pin)));
531:         }
532:         for (name, icon, route, count, loc) in rows {
533:             // Un-pin pop: the row shrinks away over 0.22 s before being removed.
534:             let k = loc.as_ref().and_then(|l| self.pin_anim.get(&l.path)).map(|s| ((self.time - *s) / 0.22).clamp(0.0, 1.0) as f32).unwrap_or(0.0);
535:             if k >= 0.99 {
536:                 continue;
537:             }
538:             if k > 0.0 {
539:                 ui.ctx().request_repaint();
540:             }
541:             let hh = 32.0 * (1.0 - k);
542:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, hh));
543:             let active = cur == route;
544:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
545:             let dropping = self.drag.is_some() && visible && ui.rect_contains_pointer(rect);
546:             if visible {
547:                 if let Some(l) = &loc {
548:                     DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(l.clone()), rect)));
549:                 }
550:                 self.sb_row(ui, rect, icon, &name, active, count.map(|c| c.to_string()), dropping, &format!("place-{}", name));
551:             }
552:             if visible {
553:                 let r = self.hit(ui, rect, ("sbrow", format!("place-{}", name)), Sense::click());
554:                 if r.clicked() {
555:                     self.push_act(Act::Nav(route.clone()));
556:                 }
557:                 if r.secondary_clicked() {
558:                     if let Some(l) = loc.clone() {
559:                         self.menu = Some(Menu { kind: MenuKind::Place, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: Some(l), device: None, sub: None, age: 0.0 });
560:                     }
561:                 }
562:             }
563:             y += 33.0 * (1.0 - k);
564:         }
565:         // While dragging, the Favorites block becomes a "pin here" drop zone.
566:         if let Some(drag) = self.drag.as_ref() {
567:             if let Some(src) = drag.items.first().cloned() {
568:                 let already = self.lib(|l| l.pins.contains(&src));
569:                 if !already {
570:                     let fav_top = nav.top() + 34.0;
571:                     let zone = Rect::from_min_max(pos2(x0 - 2.0, fav_top), pos2(x0 + w + 2.0, y.max(fav_top + 40.0).min(nav.bottom())));
572:                     let over = ui.rect_contains_pointer(zone);
573:                     if over {
574:                         p.rect_stroke(zone.shrink(1.0), cr(12.0), egui::Stroke::new(1.6, th.accent), egui::StrokeKind::Inside);
575:                         grad_fill(&p, zone, 12.0, alpha(th.accent, 0.12), alpha(th.accent, 0.05));
576:                         p.text(pos2(zone.center().x, zone.center().y), Align2::CENTER_CENTER, "Pin to Favorites", f_semi(T_META), th.accent_ink);
577:                         ui.ctx().request_repaint();
578:                     }
579:                     DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Pin(src), zone)));
580:                 }
581:             }
582:         }
583:         // ── Locations
584:         y += 14.0;
585:         label(y, "Locations", None);
586:         y += 23.0;
587:         for d in self.devices.clone() {
588:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
589:             let active = matches!(&cur, Route::Loc(l) if d.loc.as_ref().is_some_and(|dl| l == dl || (d.kind != DeviceKind::Internal && l.fs == dl.fs && l.starts_with(dl))));
590:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
591:             let dropping = self.drag.is_some() && visible && d.mounted && ui.rect_contains_pointer(rect);
592:             if visible {
593:                 if let (Some(l), true) = (&d.loc, d.mounted) {
594:                     DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(l.clone()), rect)));
595:                 }
596:                 self.sb_row_device(ui, rect, &d, active, dropping);
597:                 let r = self.hit(ui, rect, ("dev", &d.id), Sense::click());
598:                 if r.clicked() {
599:                     match (&d.loc, d.mounted, d.kind) {
600:                         (_, _, DeviceKind::Phone) => self.push_act(Act::Modal(Modal::Phone)),
601:                         (Some(l), true, _) => self.push_act(Act::Nav(Route::Loc(l.clone()))),
602:                         _ => self.push_act(Act::Mount(d.id.clone())),
603:                     }
604:                 }
605:                 if r.secondary_clicked() {
606:                     self.menu = Some(Menu { kind: MenuKind::Device, pos: ui.ctx().pointer_latest_pos().unwrap_or(rect.center()), target: d.loc.clone(), device: Some(d.id.clone()), sub: None, age: 0.0 });
607:                 }
608:             }
609:             y += 33.0;
610:         }
611:         {
612:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 32.0));
613:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
614:             if visible {
615:                 if self.sb_row(ui, rect, "add", "Mount a device\u{2026}", false, None, false, "mount-dev").clicked() {
616:                     self.push_act(Act::Modal(Modal::Devices));
617:                 }
618:             }
619:             y += 33.0;
620:         }
621:         // ── Folder tree
622:         y += 14.0;
623:         label(y, "Folders", None);
624:         y += 23.0;
625:         let now = self.time;
626:         let flat = self.tree_flat(now);
627:         for (loc, depth, name, has_kids, open) in flat {
628:             let rect = Rect::from_min_size(pos2(x0, y), vec2(w, 28.0));
629:             let visible = rect.bottom() > nav.top() - 4.0 && rect.top() < nav.bottom() + 4.0;
630:             if visible {
631:                 let active = cur == Route::Loc(loc.clone());
632:                 let dropping = self.drag.is_some() && ui.rect_contains_pointer(rect);
633:                 DROP_TARGETS.with(|v| v.borrow_mut().push((DropTarget::Place(loc.clone()), rect)));
634:                 let r = self.hit(ui, rect, ("tree", &loc), Sense::click());
635:                 if active || dropping {
636:                     p.rect_filled(rect, cr(10.0), th.accent_tint);
637:                 } else if r.is_pointer_button_down_on() {
638:                     p.rect_filled(rect, cr(10.0), th.row_press);
639:                 } else if r.hovered() {
640:                     p.rect_filled(rect, cr(10.0), th.row_hover);
641:                 }
642:                 let ind = 6.0 + depth as f32 * 14.0;
643:                 if has_kids {
644:                     let cb = Rect::from_center_size(pos2(rect.left() + ind + 9.0, rect.center().y), vec2(20.0, 20.0));
645:                     let cresp = self.hit(ui, cb, ("treechev", &loc), Sense::click());
646:                     let t = spring_to(ui.ctx(), ("tree-rot", &loc), if open { 1.0 } else { 0.0 }, 320.0, 24.0);
647:                     if cresp.hovered() {
648:                         p.circle_filled(cb.center(), 9.0, th.row_press);
649:                     }
650:                     let ang = t * std::f32::consts::FRAC_PI_2;
651:                     let rot = |v: egui::Vec2| vec2(v.x * ang.cos() - v.y * ang.sin(), v.x * ang.sin() + v.y * ang.cos());
652:                     let s = egui::Stroke::new(1.6, if cresp.hovered() { th.ink2 } else { th.ink4 });
