461:     fn tree_children(&mut self, loc: &Location, now: f64) -> Vec<Location> {
462:         if let Some((t, v)) = self.tree_cache.get(loc) {
463:             if now - *t < 3.0 {
464:                 return v.clone();
465:             }
466:         }
467:         let v = self
468:             .be
469:             .registry
470:             .get(&loc.fs)
471:             .and_then(|fs| fs.list(&loc.path).ok())
472:             .map(|l| {
473:                 let mut d: Vec<Entry> = l.into_iter().filter(|e| e.is_dir && !e.hidden).collect();
474:                 d.sort_by(|a, b| natural_cmp(&a.name, &b.name));
475:                 d.into_iter().map(|e| e.loc).collect::<Vec<_>>()
476:             })
477:             .unwrap_or_default();
478:         self.tree_cache.insert(loc.clone(), (now, v.clone()));
479:         v
480:     }
