482:     /// Flattened, depth-first view of the expanded folder tree rooted at Home.
483:     fn tree_flat(&mut self, now: f64) -> Vec<(Location, usize, String, bool, bool)> {
484:         let root = self.be.home();
485:         if !self.tree_init {
486:             self.tree_init = true;
487:             self.tree_open.insert(root.clone());
488:         }
489:         let mut out = vec![];
490:         let mut stack = vec![(root, 0usize)];
491:         while let Some((loc, depth)) = stack.pop() {
492:             let kids = self.tree_children(&loc, now);
493:             let open = self.tree_open.contains(&loc);
494:             let name = if depth == 0 { "Home".to_string() } else { loc.name() };
495:             out.push((loc.clone(), depth, name, !kids.is_empty(), open));
496:             if open && depth < 6 && out.len() < 300 {
497:                 for k in kids.iter().rev() {
498:                     stack.push((k.clone(), depth + 1));
499:                 }
500:             }
501:         }
502:         out
503:     }
