719:             if drop && !active {
720:                 p.rect_stroke(rect.shrink(0.5), cr(10.0), egui::Stroke::new(1.5, alpha(th.accent, 0.6)), egui::StrokeKind::Inside);
721:             }
722:         } else if r.is_pointer_button_down_on() {
723:             p.rect_filled(rect, cr(10.0), th.row_press);
724:         } else if r.hovered() {
725:             p.rect_filled(rect, cr(10.0), th.row_hover);
726:         }
727:         let col = if active { th.accent_ink } else { th.ink2 };
728:         self.ico(p, icon, if active { Ic::Filled } else { Ic::Duo }, pos2(rect.left() + 19.0, rect.center().y), 16.0, if active { th.accent_ink } else { th.ink3 });
729:         let f = if active { f_semi(T_BODY) } else { f_medium(T_BODY) };
730:         let max = rect.width() - 58.0;
731:         let label = self.fit(p, name, &f, max);
732:         p.text(pos2(rect.left() + 37.0, rect.center().y), Align2::LEFT_CENTER, label, f, col);
733:         if let Some(t) = tail {
734:             p.text(pos2(rect.right() - 12.0, rect.center().y), Align2::RIGHT_CENTER, t, f_medium(T_META), if active { alpha(th.accent_ink, 0.9) } else { th.ink4 });
735:         }
736:         r
737:     }
