739:     fn sb_row_tag(&self, ui: &Ui, rect: Rect, name: &str, color: Color32, active: bool, n: usize, drop: bool) -> Response {
740:         let r = self.hit(ui, rect, ("tag", name), Sense::click());
741:         let p = ui.painter();
742:         let th = &self.th;
743:         if active || drop {
744:             p.rect_filled(rect, cr(10.0), th.accent_tint);
745:             if drop && !active {
746:                 p.rect_stroke(rect.shrink(0.5), cr(10.0), egui::Stroke::new(1.5, alpha(th.accent, 0.6)), egui::StrokeKind::Inside);
747:             }
748:         } else if r.hovered() {
749:             p.rect_filled(rect, cr(10.0), th.row_hover);
750:         }
751:         let c0 = pos2(rect.left() + 19.0, rect.center().y);
