56: pub fn unique_name(v: &dyn Vfs, dir: &Location, name: &str, suffix: Option<&str>) -> String {
57:     let (stem, ext) = match name.rfind('.') {
58:         Some(i) if i > 0 => (&name[..i], &name[i..]),
59:         _ => (name, ""),
