66:         None => stem.to_string(),
67:     };
68:     if suffix.is_some() {
69:         let c = format!("{}{}", base, ext);
70:         if !v.exists(&dir.join(&c).path) {
71:             return c;
72:         }
73:     }
74:     for i in 1..10_000 {
75:         let c = if suffix.is_some() { format!("{} {}{}", base, i + 1, ext) } else { format!("{} ({}){}", base, i, ext) };
