266:     pub fn rename(&self, loc: &Location, new_name: &str) -> Result<Location, String> {
267:         let name = new_name.trim();
268:         if name.is_empty() || name.contains('/') {
269:             return Err("That name isn\u{2019}t valid".into());
270:         }
271:         let Some(parent) = loc.parent() else { return Err("Can\u{2019}t rename this location".into()) };
272:         let to = parent.join(name);
273:         if to == *loc {
274:             return Ok(to);
275:         }
276:         self.vfs(loc)?.rename(&loc.path, &to.path).map_err(|e| match e {
277:             FsError::Exists => format!("\u{201c}{}\u{201d} already exists here", name),
278:             e => e.to_string(),
279:         })?;
280:         self.library.write().unwrap().rekey(loc, &to);
281:         self.search.invalidate(&parent);
282:         Ok(to)
283:     }
