287:     pub fn read_text(&self, loc: &Location, limit: usize) -> Result<String, String> {
288:         let b = self.read_bytes(loc, limit)?;
289:         if b.iter().take(2048).any(|c| *c == 0) {
290:             return Err("Binary file".into());
291:         }
292:         Ok(String::from_utf8_lossy(&b).to_string())
293:     }
