446:     fn device_op(&self, id: &str, op: &'static str) {
447:         let (providers, tx, reg, id) = (self.providers.clone(), self.tx.clone(), self.registry.clone(), id.to_string());
448:         let store = self.devices.clone();
449:         spawn(move || {
450:             let Some(p) = providers.iter().find(|p| p.owns(&id)) else {
451:                 let _ = tx.send(Event::DeviceOp { id, op, result: Err("Unknown device".into()) });
452:                 return;
453:             };
454:             let result = match op {
455:                 "mount" => p.mount(&id).map(|m| {
456:                     if let Some(v) = m.vfs {
457:                         reg.insert(v);
458:                     }
459:                     Some(m.loc)
460:                 }),
461:                 "eject" => p.eject(&id).map(|_| None),
462:                 _ => p.unmount(&id).map(|_| None),
463:             };
464:             let all: Vec<Device> = providers.iter().flat_map(|p| p.list()).collect();
465:             *store.lock().unwrap() = all.clone();
466:             let _ = tx.send(Event::DeviceOp { id, op, result });
467:             let _ = tx.send(Event::Devices(all));
468:         });
469:     }
