521:                 let v = reg.get(&loc.fs)?;
522:                 let dir = std::env::temp_dir().join("smart-files-open");
523:                 std::fs::create_dir_all(&dir).ok()?;
524:                 let p = dir.join(&name);
525:                 let mut r = v.open_read(&loc.path).ok()?;
526:                 let mut w = std::fs::File::create(&p).ok()?;
527:                 std::io::copy(&mut r, &mut w).ok()?;
528:                 Some(p)
529:             });
530:             let res = match &app {
531:                 Some(a) => apps.open_with(a, &name, real.as_deref()),
532:                 None => apps.open_default(&name, real.as_deref()),
533:             };
534:             let (text, ok) = match res {
535:                 Ok(t) => (t, true),
536:                 Err(e) => (e, false),
537:             };
538:             let _ = tx.send(Event::Message { text, ok });
