554:     // ───────── pump ─────────
555:     pub fn poll(&mut self) -> Vec<Event> {
556:         let mut out: Vec<Event> = vec![];
557:         // paced (showcase) transfers: progress is driven by wall-clock time so the UI animates smoothly
558:         let now = crate::exec::now_millis();
559:         let mut finished: Vec<(u64, JobKind)> = vec![];
560:         {
561:             let mut q = self.paced.lock().unwrap();
562:             q.retain_mut(|j| {
563:                 let frac = ((now - j.started_ms) as f32 / 1000.0) / j.secs;
564:                 if now - j.last >= 16 || frac >= 1.0 {
565:                     j.last = now;
566:                     let total = 1000u64;
567:                     let done = ((frac.clamp(0.0, 0.999) * total as f32) as u64).max(1);
568:                     out.push(Event::Job(JobEvent::Progress { id: j.id, done, total, current: j.kind.srcs().first().map(|l| l.name()).unwrap_or_default() }));
569:                 }
570:                 if frac >= 1.0 {
571:                     finished.push((j.id, j.kind.clone()));
572:                     return false;
573:                 }
574:                 true
575:             });
576:         }
577:         for (id, kind) in finished {
578:             match ops::run_sync(&self.registry, &kind) {
579:                 Ok((created, touched)) => {
580:                     for t in &touched {
581:                         self.search.invalidate(t);
582:                     }
583:                     let n = created.len();
584:                     out.push(Event::Job(JobEvent::Finished { id, created, touched }));
585:                     let verb = match kind { JobKind::Move { .. } => "Moved", _ => "Copied" };
586:                     out.push(Event::Message { text: format!("{} {} item{}", verb, n, if n == 1 { "" } else { "s" }), ok: true });
587:                 }
588:                 Err(e) => {
589:                     out.push(Event::Job(JobEvent::Failed { id, error: e.to_string() }));
590:                 }
591:             }
592:         }
593:         self.be_poll_rest(&mut out);
594:         out
595:     }
