        let p = cui.painter().clone();
        let shown = rect.translate(off);
        elevate(&p, &th, shown, R_WIN, if active { 5 } else { 3 });
        // glass body (same recipe as the Files window)
        let (_, sz, blur) = self.active_wall();
        if let Some(b) = blur {
