[workspace]
resolver = "2"
members = ["crates/smart-core", "crates/smart-ui-egui", "crates/xtask"]

[workspace.package]
version = "0.1.0"
edition = "2021"
license = "MIT"

[profile.release]
opt-level = 3
lto = "fat"
codegen-units = 1
panic = "abort"
strip = true

[profile.wasm]
inherits = "release"
opt-level = "s"
lto = true

[profile.dev]
opt-level = 1

# Sandbox-friendly profiles (2-core CI): fast iteration, same codegen as release elsewhere.
[profile.wasmfast]
inherits = "release"
opt-level = 1
lto = false
codegen-units = 2
strip = false

[profile.nativefast]
inherits = "release"
opt-level = 1
lto = false
codegen-units = 2
strip = false
[package]
name = "smart-ui-egui"
description = "egui frontend for Smart Files (desktop + WebAssembly)"
version.workspace = true
edition.workspace = true
license.workspace = true

[lib]
crate-type = ["cdylib", "rlib"]

[[bin]]
name = "smart-files"
path = "src/main.rs"

[features]
default = ["audio"]
audio = ["smart-core/audio"]

[dependencies]
smart-core = { path = "../smart-core", default-features = true }
eframe = { version = "0.37", default-features = false, features = ["glow", "default_fonts", "x11", "wayland"] }
egui = "0.37"
vt100 = "0.15"
image = { version = "0.25", default-features = false, features = ["png", "jpeg"] }

[target.'cfg(target_arch = "wasm32")'.dependencies]
wasm-bindgen = "0.2"
wasm-bindgen-futures = "0.4"
web-sys = { version = "0.3", features = ["Window", "Document", "HtmlCanvasElement", "Element", "console", "Location"] }
console_error_panic_hook = "0.1"
